package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assumptions.assumeTrue;

import java.io.IOException;
import java.nio.file.FileStore;
import java.nio.file.FileSystem;
import java.nio.file.Path;
import java.nio.file.PathMatcher;
import java.nio.file.WatchService;
import java.nio.file.attribute.BasicFileAttributes;
import java.nio.file.attribute.UserPrincipalLookupService;
import java.nio.file.spi.FileSystemProvider;
import java.util.Collections;
import java.util.Set;
import org.junit.jupiter.api.Test;

class GzipBasicFileAttributeViewMutaGate2Test {

  private static final class StubFileSystem extends FileSystem {
    @Override
    public FileSystemProvider provider() {
      return null;
    }

    @Override
    public void close() {}

    @Override
    public boolean isOpen() {
      return true;
    }

    @Override
    public boolean isReadOnly() {
      return true;
    }

    @Override
    public String getSeparator() {
      return "/";
    }

    @Override
    public Iterable<Path> getRootDirectories() {
      return Collections.emptyList();
    }

    @Override
    public Iterable<FileStore> getFileStores() {
      return Collections.emptyList();
    }

    @Override
    public Set<String> supportedFileAttributeViews() {
      return Collections.singleton("basic");
    }

    @Override
    public Path getPath(String first, String... more) {
      throw new UnsupportedOperationException();
    }

    @Override
    public PathMatcher getPathMatcher(String syntaxAndPattern) {
      throw new UnsupportedOperationException();
    }

    @Override
    public UserPrincipalLookupService getUserPrincipalLookupService() {
      throw new UnsupportedOperationException();
    }

    @Override
    public WatchService newWatchService() throws IOException {
      throw new UnsupportedOperationException();
    }
  }

  private static final class Outcome {
    final Class<?> type;
    final BasicFileAttributes attributes;

    Outcome(Class<?> type, BasicFileAttributes attributes) {
      this.type = type;
      this.attributes = attributes;
    }
  }

  private static Outcome attempt(GzipBasicFileAttributeView view) {
    try {
      BasicFileAttributes attrs = view.readAttributes();
      return new Outcome(null, attrs);
    } catch (Throwable t) {
      return new Outcome(t.getClass(), null);
    }
  }

  @Test
  void readAttributesOutcomeIsStableAcrossCalls() {
    Object[] constants = SingleEntryArchiveFormat.class.getEnumConstants();
    assumeTrue(constants != null && constants.length > 0);
    SingleEntryArchiveFormat format = (SingleEntryArchiveFormat) constants[0];

    SingleEntryArchivePath path =
        new SingleEntryArchivePath(new StubFileSystem(), format, true, "entry");
    GzipBasicFileAttributeView view = new GzipBasicFileAttributeView(path);

    Outcome first = attempt(view);
    Outcome second = attempt(view);

    assertEquals(first.type, second.type);
    if (first.type == null) {
      assertNotNull(first.attributes);
      assertNotNull(second.attributes);
      assertEquals(first.attributes.isDirectory(), second.attributes.isDirectory());
      assertEquals(first.attributes.isRegularFile(), second.attributes.isRegularFile());
      assertEquals(first.attributes.size(), second.attributes.size());
    }
  }
}

